import React, { useState } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const QuanLyHoaDon = () => {
    const now = new Date();
    const currentMonth = now.getMonth() + 1;
    const currentYear = now.getFullYear();

    const [selectedMonth, setSelectedMonth] = useState(currentMonth);
    const [selectedYear, setSelectedYear] = useState(currentYear);

    const years = [2024, 2025, 2026];
    const months = Array.from({ length: 12 }, (_, i) => i + 1);

    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    const isCurrentOrFuture = selectedYear > currentYear || (selectedYear === currentYear && selectedMonth >= currentMonth);
    const totalReceived = isCurrentOrFuture ? 0 : (5000000 * 45);

    return (
        <div style={{
            height: '100vh', // KHUNG CỨNG 1: Ép toàn màn hình
            display: 'flex', 
            flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, 
            backgroundSize: 'cover',
            backgroundPosition: 'center', 
            overflow: 'hidden', // KHUNG CỨNG 2: Tuyệt đối không cuộn trang web chính
            padding: '20px',
            boxSizing: 'border-box'
        }}>

            {/* Vỏ bọc Glass-card giống trang Cư dân */}
            <div style={{ 
                flex: 1, 
                display: 'flex', 
                flexDirection: 'column', 
                backgroundColor: 'rgba(255,255,255,0.1)', 
                borderRadius: '30px', 
                overflow: 'hidden', // Khóa nội dung bên trong card
                minHeight: 0 
            }}>

                {/* Header */}
                <div style={{ padding: '20px', color: '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexShrink: 0 }}>
                    <h2 style={{ margin: 0, textShadow: '1px 1px 4px rgba(0,0,0,0.5)' }}>Quản lý hoá đơn</h2>
                    <div style={{ display: 'flex', gap: '10px' }}>
                        <select value={selectedMonth} onChange={(e) => setSelectedMonth(parseInt(e.target.value))} style={{ padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold' }}>
                            {months.map(m => <option key={m} value={m}>Tháng {m}</option>)}
                        </select>
                        <select value={selectedYear} onChange={(e) => setSelectedYear(parseInt(e.target.value))} style={{ padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold' }}>
                            {years.map(y => <option key={y} value={y}>Năm {y}</option>)}
                        </select>
                    </div>
                </div>

                {/* Body chứa 2 cột */}
                <div style={{ flex: 1, padding: '0 20px 20px 20px', display: 'flex', gap: '30px', overflow: 'hidden', minHeight: 0 }}>

                    {/* CỘT TRÁI: DANH SÁCH PHÒNG (Cuộn riêng) */}
                    <div style={{ 
                        width: '210px', display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', 
                        gap: '6px', alignContent: 'flex-start', overflowY: 'auto',
                        padding: '12px', backgroundColor: 'rgba(255,255,255,0.1)',
                        borderRadius: '20px', border: '1px solid rgba(255,255,255,0.1)'
                    }}>
                        {allRooms.map(room => (
                            <div key={room} style={{ 
                                background: !isCurrentOrFuture ? 'rgba(255,255,255,0.8)' : '#ffcc00', 
                                color: '#333', padding: '8px 0', borderRadius: '8px', 
                                textAlign: 'center', fontSize: '11px', fontWeight: 'bold'
                            }}>
                                {room}
                            </div>
                        ))}
                    </div>

                    {/* CỘT PHẢI: CHI TIẾT (KHUNG TRẮNG CỨNG) */}
                    <div style={{ 
                        flex: 1, backgroundColor: '#ffffff', borderRadius: '25px', 
                        padding: '40px', display: 'flex', flexDirection: 'column',
                        color: '#000', boxShadow: '0 8px 32px 0 rgba(0, 0, 0, 0.3)',
                        minHeight: 0, overflow: 'hidden' // Khóa cứng form trắng
                    }}>

                        <h1 style={{ 
                            fontSize: '60px', margin: '0 0 30px 0', color: '#8b5e5e',
                            borderBottom: '2px solid #eee', paddingBottom: '10px', fontWeight: '800',
                            flexShrink: 0 
                        }}>
                            THÁNG: {selectedMonth}/{selectedYear}
                        </h1>

                        <div style={{ display: 'flex', alignItems: 'center', fontSize: '20px', marginBottom: '30px', flexShrink: 0 }}>
                            <span style={{ width: '280px', fontWeight: 'bold', color: '#555' }}>Tổng tiền đã nhận:</span>
                            <span style={{ fontWeight: '800', color: totalReceived > 0 ? '#28a745' : '#999', fontSize: '28px' }}>
                                {totalReceived.toLocaleString()}đ
                            </span>
                        </div>

                        <h3 style={{ marginBottom: '10px', color: '#555', flexShrink: 0 }}>Lịch sử giao dịch</h3>

                        {/* ĐÂY LÀ KHUNG CUỘN CHUẨN NHƯ KHUNG CHAT (ẢNH 4) */}
                        <div style={{ 
                            flex: 1, 
                            overflowY: 'auto', 
                            minHeight: 0, // QUAN TRỌNG NHẤT: Ép cuộn tại đây, không cho dãn form
                            border: '1px solid #eee',
                            borderRadius: '15px',
                            backgroundColor: '#f9f9f9',
                            boxSizing: 'border-box'
                        }}>
                            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                                <thead style={{ position: 'sticky', top: 0, backgroundColor: '#f9f9f9', zIndex: 1 }}>
                                    <tr style={{ textAlign: 'left', color: '#888', fontSize: '14px' }}>
                                        <th style={{ padding: '12px', borderBottom: '2px solid #eee' }}>Phòng</th>
                                        <th style={{ padding: '12px', borderBottom: '2px solid #eee' }}>Số tiền</th>
                                        <th style={{ padding: '12px', borderBottom: '2px solid #eee' }}>Nội dung</th>
                                        <th style={{ padding: '12px', borderBottom: '2px solid #eee' }}>Thời gian</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {!isCurrentOrFuture ? (
                                        allRooms.map(room => (
                                            <tr key={room} style={{ borderBottom: '1px solid #eee' }}>
                                                <td style={{ padding: '12px', fontWeight: 'bold' }}>{room}</td>
                                                <td style={{ padding: '12px', color: '#28a745', fontWeight: '600' }}>5.000.000đ</td>
                                                <td style={{ padding: '12px', fontSize: '14px' }}>Tiền phòng T{selectedMonth}</td>
                                                <td style={{ padding: '12px', fontSize: '12px', color: '#999' }}>01/{selectedMonth.toString().padStart(2, '0')}/{selectedYear}</td>
                                            </tr>
                                        ))
                                    ) : (
                                        <tr>
                                            <td colSpan="4" style={{ textAlign: 'center', padding: '100px 0', color: '#ccc', fontStyle: 'italic' }}>
                                                Chưa có dữ liệu giao dịch...
                                            </td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default QuanLyHoaDon;
